# Notes produced in English by the diff and the follow-up, mapped to their keys.
KNOWN_NOTES = {
    STRINGS["en"]["note_mixed"]: "note_mixed",
    STRINGS["en"]["note_no_snapshot"]: "note_no_snapshot",
    STRINGS["en"]["note_marked_unresolved"]: "note_marked_unresolved",
    STRINGS["en"]["note_design_open"]: "note_design_open",
}


def supported(lang: str | None) -> str:
    """'es-ES' -> 'es'; anything without a table -> English."""
    code = (lang or DEFAULT).lower().replace("_", "-").split("-")[0]
    return code if code in STRINGS else DEFAULT


def table(lang: str | None = None) -> dict[str, str]:
    code = supported(lang)
    return {**STRINGS[DEFAULT], **STRINGS[code]}


def note(text: str, t: dict[str, str]) -> str:
    key = KNOWN_NOTES.get(text)
    return t[key] if key else text
